import {VARIABLES,DIMENSIONS,PATHOLOGIES,calculate,actionsFor,PERIODICITY,exportCase,importCase,toCSV,applyOverride} from './clinical.js';
import {prestratify} from './extractor.js';
import {allCases,saveCase,deleteCase,clearCases} from './storage.js';
let form={values:{},pathologies:[],adultClinic:true};
const $=s=>document.querySelector(s); const el=(t,a={},h='')=>{const e=document.createElement(t);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));e.innerHTML=h;return e};
function render(){renderForm(); update(); renderSaved();}
function renderForm(){const p=$('#pathologies'); p.innerHTML=PATHOLOGIES.map(([id,l])=>`<label><input type="checkbox" value="${id}"> ${l}</label>`).join(''); p.onchange=e=>{form.pathologies=[...p.querySelectorAll(':checked')].map(i=>i.value); form.mainPathology=form.pathologies[0]||''; update();}; $('#variables').innerHTML=''; for(const [dim,d] of Object.entries(DIMENSIONS)){const sec=el('section',{class:'panel'},`<h2>${d.label} <span id="sub-${dim}" class="chip"></span></h2>`); VARIABLES.filter(v=>v.dim===dim).forEach(v=>{const card=el('div',{class:'var-card'},`<h3>${v.label}</h3><p>${v.help||''}</p><div id="ctrl-${v.id}"></div>`); const c=card.querySelector('div'); if(v.type==='age') c.innerHTML='<input id="age" type="number" min="0" placeholder="Edad"><label><input id="adultClinic" type="checkbox" checked> Atendido en consulta de adultos</label><select data-var="age"><option value="pending">Pendiente</option><option value="adult">Aplicar edad registrada</option><option value="pediatric">Edad pediátrica: derivar</option></select>'; else if(v.type==='bmi') c.innerHTML='<input id="bmi" type="number" step="0.1" placeholder="IMC"><select data-var="bmi"><option value="pending">Pendiente</option><option value="set">Aplicar IMC registrado</option></select>'; else if(v.type==='goals') c.innerHTML='<select data-var="pharmGoals"><option value="pending">Pendiente</option><option value="yes">Sí, alcanzados</option><option value="no">No alcanzados / inicio reciente</option></select>'; else c.innerHTML=`<select data-var="${v.id}"><option value="pending">Pendiente</option><option value="yes">Sí</option><option value="no">No</option></select>`; sec.append(card);}); $('#variables').append(sec);} document.querySelectorAll('select[data-var]').forEach(s=>s.onchange=()=>{form.values[s.dataset.var]=s.value; update();}); document.querySelectorAll('input').forEach(i=>i.oninput=()=>{form[i.id]=i.type==='checkbox'?i.checked:i.value; update();});}
function update(){form.pseudoId=$('#pseudo').value;form.center=$('#center').value;form.pharmacist=$('#pharmacist').value; let r=calculate(form); try{r=applyOverride(r,{priority:$('#overridePriority').value,justification:$('#overrideJustification').value,motive:$('#overrideMotive').value})}catch(e){} $('#score').textContent=`${r.total}/59`; $('#priority').textContent=r.finalPriority; $('#provisional').textContent=r.pending?'Provisional: datos pendientes':'Completo'; $('#auto').textContent=r.pediatric||r.automaticCauses.join('; ')||'Sin prioridad automática'; for(const [k,v] of Object.entries(r.subtotals)) $('#sub-'+k)?.replaceChildren(document.createTextNode(`${v}/${DIMENSIONS[k].max}`)); $('#detail').innerHTML=r.details.map(d=>`<tr><td>${d.variable.label}</td><td>${d.response}</td><td>${d.points}</td></tr>`).join(''); $('#actions').innerHTML=Object.values(actionsFor(r.finalPriority)).map(g=>`<h3>${g.label}</h3><ul>${g.items.map(i=>`<li>${i}</li>`).join('')}</ul>`).join('')+`<p><strong>Periodicidad:</strong> ${PERIODICITY[r.finalPriority]}</p>`; window.currentResult=r;}
['pseudo','center','pharmacist','overridePriority','overrideJustification','overrideMotive'].forEach(id=>setTimeout(()=>$('#'+id).oninput=update));
$('#save').onclick=()=>{form=saveCase(form); renderSaved(); alert('Caso guardado localmente')}; $('#exportJson').onclick=()=>download('caso-respiratorio.json',exportCase(form)); $('#exportCsv').onclick=()=>download('detalle-respiratorio.csv',toCSV(window.currentResult.details)); $('#summary').onclick=()=>download('resumen-clinico.txt',report()); $('#print').onclick=()=>print(); $('#import').onchange=e=>e.target.files[0].text().then(t=>{try{form=importCase(t); render()}catch(err){alert('JSON inválido o incompatible')}}); $('#clear').onclick=()=>confirm('¿Borrar todos los casos locales?')&&(clearCases(),renderSaved()); $('#extract').onclick=()=>{const res=prestratify($('#clinicalText').value); $('#clinicalText').value=''; $('#extractResults').innerHTML=res.filter(x=>x.status!=='no_mencionado').map(x=>`<div class="proposal"><b>${VARIABLES.find(v=>v.id===x.variableId).label}</b>: ${x.status} (${x.certainty})<br><small>${x.fragment}</small><br><em>${x.rule}</em><button data-accept="${x.variableId}" data-val="${x.proposal}">Confirmar</button><button>Rechazar</button></div>`).join('')||'Sin propuestas'; document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>{form.values[b.dataset.accept]=b.dataset.val==='set_age'||b.dataset.val==='set_bmi'?'set':b.dataset.val; update();});};
function renderSaved(){ $('#saved').innerHTML=allCases().map(c=>`<li>${c.pseudoId||c.id} <button data-load="${c.id}">Cargar</button> <button data-del="${c.id}">Borrar</button></li>`).join(''); document.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{form=allCases().find(c=>c.id===b.dataset.load); render()}); document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>confirm('¿Borrar este caso?')&&(deleteCase(b.dataset.del),renderSaved()));}
function download(n,t){const a=el('a',{href:URL.createObjectURL(new Blob([t],{type:'text/plain'})),download:n});a.click();}
function report(){return `SIAF-CMO Respiratorio\nPaciente: ${form.pseudoId||'seudónimo'}\nPrioridad calculada: ${window.currentResult.calculatedPriority}\nPrioridad final: ${window.currentResult.finalPriority}\nPuntuación: ${window.currentResult.total}/59\nEstado: ${window.currentResult.pending?'Provisional':'Completo'}`}
render();
